<script lang="ts">import { goto } from '$app/navigation'; import { api } from '$lib/api'; let email = ''; let password = ''; let error = ''; let busy = false; async function submit() { busy = true; error = ''; try { await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ email, password, rememberMe: true }) }); await goto('/staff'); } catch (e) { error = e instanceof Error ? e.message : 'Sign-in failed.'; } finally { busy = false; } }</script>
<main class="auth-shell"><section class="auth-card"><span class="eyebrow">TASK KARATE SCHOOL</span><h1>Staff sign-in</h1><p class="muted">Use your server-managed staff account. This app does not store a browser session or fallback credentials.</p>{#if error}<div class="error">{error}</div>{/if}<form on:submit|preventDefault={submit}><label>Email<input type="email" bind:value={email} autocomplete="username" required /></label><label>Password<input type="password" bind:value={password} autocomplete="current-password" required /></label><button class="button" disabled={busy}>{busy ? 'Signing in…' : 'Sign in'}</button></form><a class="back-link" href="/">← Public schedule</a></section></main>
